#!/bin/bash
# Sync contract from backend to web

set -e

echo "Syncing contract from backend..."

# Run backend export script
cd "$(dirname "$0")/../.."
echo "Running backend export_contract.py..."
uv run python backend/scripts/export_contract.py

# Install/update web dependencies if needed
cd web
echo "Installing web dependencies..."
pnpm install --frozen-lockfile

# Run contract sync (types already generated by export_contract.py)
echo "Contract sync complete!"

# Verify generated types exist
if [ -f "src/contract/api.ts" ]; then
    echo "✓ TypeScript types generated at src/contract/api.ts"
else
    echo "✗ TypeScript types not found!"
    exit 1
fi